if ( hash( 'sha256', (string) get_post_field( 'post_content', $id ) ) !== $expected_hash ) {
  throw new RuntimeException( 'About page changed; refusing update.' );
}
$content = base64_decode( '' );
$result = wp_update_post( array(
  'ID' => $id,
